def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    def runs(values, color):
        result = []
        i = 0
        while i < len(values):
            if values[i] != color:
                i += 1
                continue
            j = i
            while j + 1 < len(values) and values[j + 1] == color:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    candidates = []
    colors = set(v for row in grid for v in row) - {bg}
    for color in colors:
        for orient, edge_a, edge_b, side_a, side_b in (
            ("h", grid[0], grid[-1], "top", "bottom"),
            ("v", [grid[r][0] for r in range(h)],
                  [grid[r][-1] for r in range(h)], "left", "right"),
        ):
            for a in runs(edge_a, color):
                for b in runs(edge_b, color):
                    score = (a[1] - a[0] + 1) + (b[1] - b[0] + 1)
                    candidates.append((score, orient, color, a, b, side_a, side_b))

    if not candidates:
        return [row[:] for row in grid]

    _, orient, wall, run_a, run_b, side_a, side_b = max(candidates)
    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, wall)]
    if not markers:
        return [row[:] for row in grid]

    from collections import Counter
    marker_color = Counter(v for _, _, v in markers).most_common(1)[0][0]
    markers = [(r, c) for r, c, v in markers if v == marker_color]
    axis_pos = [c if orient == "h" else r for r, c in markers]

    def count_in(run):
        return sum(run[0] <= p <= run[1] for p in axis_pos)

    # Choose the boundary segment on which the markers are aligned.
    if count_in(run_a) >= count_in(run_b):
        source_run, other_run = run_a, run_b
        source_side, other_side = side_a, side_b
    else:
        source_run, other_run = run_b, run_a
        source_side, other_side = side_b, side_a

    out = [row[:] for row in grid]

    for r, c in markers:
        p = c if orient == "h" else r
        if not (source_run[0] <= p <= source_run[1]):
            continue

        mapped = other_run[0] + (p - source_run[0])

        # Trace from the marker to its aligned boundary segment.
        if orient == "h":
            if source_side == "top":
                for rr in range(1, r):
                    out[rr][c] = marker_color
            else:
                for rr in range(r + 1, h - 1):
                    out[rr][c] = marker_color
        else:
            if source_side == "left":
                for cc in range(1, c):
                    out[r][cc] = marker_color
            else:
                for cc in range(c + 1, w - 1):
                    out[r][cc] = marker_color

        # Continue a full line inward from the corresponding opposite segment.
        if orient == "h":
            row_range = range(1, h) if other_side == "top" else range(0, h - 1)
            for rr in row_range:
                if out[rr][mapped] != wall:
                    out[rr][mapped] = marker_color
        else:
            col_range = range(1, w) if other_side == "left" else range(0, w - 1)
            for cc in col_range:
                if out[mapped][cc] != wall:
                    out[mapped][cc] = marker_color

    for r, c in markers:
        out[r][c] = 4

    return out
